use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let mut result = String::new();
    for c in input.as_str().unwrap().chars() {
        if c.is_alphabetic() {
            let base = if c.is_uppercase() { 65 } else { 97 };
            let offset = if c.is_uppercase() { 32 } else { 0 };
            result.push((c as u8 - base + offset) as char);
        } else {
            result.push(c);
        }
    }
    Value::String(result)
}
